contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // The test: given parameters for create, if create does NOT revert then it returns a non-zero address
    // and the factory's roundImplementation and alloSettings remain as before the call.
    function run(bytes calldata encodedParameters, address ownedBy) public payable {
        // precondition: ensure caller is set as program operator so the call may proceed depending on other conditions
        // We cannot directly set programOperators in c because it's not exposed; instead we assume the checker will
        // consider both possibilities. No require on params.
        // Read before-values
        address beforeRoundImpl = c.roundImplementation(); if (__ESBMC_reverted()) return;
        address beforeAllo = c.alloSettings(); if (__ESBMC_reverted()) return;

        bool reverted;
        address returned;
        address addr = c.create(encodedParameters, ownedBy); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
            returned = address(0);
        } else {
            reverted = false;
            returned = addr;
        }

        // If the call succeeded (did not revert) then returned must be non-zero, and the factory's implementation
        // and alloSettings must be unchanged by create.
        assert(reverted || (returned != address(0) && c.roundImplementation() == beforeRoundImpl && c.alloSettings() == beforeAllo));
    }

    receive() external payable {}
}

